<script setup>
import { computed, onMounted, ref } from "vue";

const API = "/api";
const parentToken = ref(localStorage.getItem("sp_parent_jwt") || "");
const authMode = ref("pin");
const pin = ref("");
const showLogin = ref(false);
const loading = ref(true);
const error = ref("");
const notice = ref("");
const view = ref("home");
const adminTab = ref("overview");
const students = ref([]);
const currentStudent = ref(Number(localStorage.getItem("sp_stu") || 0));
const points = ref(0);
const sessions = ref([]);
const words = ref([]), math = ref([]), reading = ref(null);
const tasks = ref([]), rewards = ref([]), logs = ref([]);
const lesson = ref(null), questions = ref([]), questionIndex = ref(0), combo = ref(0), sessionId = ref(null), result = ref(null);
const newTask = ref({ title: "", type: "学习", due_date: "", points: 5 });
const newReward = ref({ name: "", cost_points: 20 });
const newStudent = ref({ name: "", username: "", avatar: "🐣", grade: 5 });
const newPin = ref("");
const isParent = computed(() => !!parentToken.value);
const hasStudent = computed(() => students.value.length > 0 && !!currentStudent.value);
const activeStudent = computed(() => students.value.find(s => s.id === currentStudent.value));
const activeQuestion = computed(() => questions.value[questionIndex.value]);
const progress = computed(() => questions.value.length ? Math.round((questionIndex.value / questions.value.length) * 100) : 0);
const units = [
  { kind: "words", title: "单词星球", sub: "认识新单词，积累词汇", className: "word", icon: "Aa" },
  { kind: "reading", title: "阅读森林", sub: "读短文，练理解能力", className: "read", icon: "阅" },
  { kind: "math", title: "数学城堡", sub: "计算与应用题挑战", className: "math", icon: "∑" }
];
function api(path, options = {}) { const sep = path.includes("?") ? "&" : "?"; const headers = { "Content-Type": "application/json", ...(options.headers || {}) }; if (parentToken.value) headers.Authorization = `Bearer ${parentToken.value}`; return fetch(`${API}${path}${options.child === false ? "" : `${sep}student_id=${currentStudent.value}`}`, { ...options, headers, body: options.body ? JSON.stringify(options.body) : undefined }).then(async r => { const data = await r.json().catch(() => null); if (!r.ok) throw new Error(data?.error || `请求失败（${r.status}）`); return data; }); }
function fail(e) { error.value = e.message || String(e); }
function shuffle(a) { return [...a].sort(() => Math.random() - .5); }
function starCount(u) { return sessions.value.filter(x => x.subject === u.kind && x.level === 1).reduce((b, x) => Math.max(b, x.stars || 0), 0); }
function totalStars() { return sessions.value.reduce((s, x) => s + (x.stars || 0), 0); }
function maxCombo() { return sessions.value.reduce((b, x) => Math.max(b, x.max_combo || 0), 0); }
function optionPool(answer, pool) { const o = [String(answer)]; shuffle(pool).forEach(x => { if (x && !o.includes(String(x)) && o.length < 4) o.push(String(x)); }); while (o.length < 4) o.push(`选项${o.length}`); return shuffle(o); }
async function load() { if (!isParent.value) return; loading.value = true; try { const ss = await api("/students", { child: false }); students.value = ss || []; if (!students.value.some(s => s.id === currentStudent.value)) currentStudent.value = students.value[0]?.id || 0; if (hasStudent.value) { const [pp, ww, mm, se] = await Promise.all([api("/points"), api("/words"), api("/math"), api("/sessions")]); points.value = pp?.total || 0; words.value = ww || []; math.value = mm || []; sessions.value = se || []; } } catch (e) { fail(e); } finally { loading.value = false; } }
async function switchStudent(id) { currentStudent.value = id; localStorage.setItem("sp_stu", String(id)); view.value = "home"; await load(); }
async function startUnit(unit) { if (!hasStudent.value) { adminTab.value = "students"; view.value = "admin"; return; } try { if (unit.kind === "reading" && !reading.value) reading.value = await api("/readings/1"); let list = []; if (unit.kind === "words") list = shuffle(words.value).slice(0, 5).map(w => ({ id: w.id, type: "word", title: w.word, subtitle: w.phonetic, answer: w.meaning, options: optionPool(w.meaning, words.value.map(x => x.meaning)) })); if (unit.kind === "math") list = shuffle(math.value).slice(0, 5).map(x => ({ id: x.id, type: "math", title: x.question, answer: String(x.answer), options: JSON.parse(x.options || "[]").map(String) })); if (unit.kind === "reading") list = shuffle(reading.value?.questions || []).slice(0, 5).map(x => { const o = [x.option_a, x.option_b, x.option_c, x.option_d].filter(Boolean).map(strip); const a = /^[A-D]$/.test(x.answer) ? o["ABCD".indexOf(x.answer)] : strip(x.answer); return { id: x.id, type: "reading", title: x.question, answer: a, options: shuffle(o) }; }); if (!list.length) throw new Error("这一关还没有题目"); const s = await api("/sessions", { method: "POST", body: { subject: unit.kind, level: 1, total: list.length } }); lesson.value = unit; questions.value = list; questionIndex.value = 0; combo.value = 0; sessionId.value = s.id; result.value = null; view.value = "lesson"; } catch (e) { fail(e); } }
function strip(v) { return String(v || "").replace(/^[A-D][.、\s]\s*/, ""); }
async function selectOption(o) { const q = activeQuestion.value; if (!q || q.picked) return; q.picked = o; q.correct = o === q.answer; try { let r; if (q.type === "word") r = await api(`/words/${q.id}/progress`, { method: "POST", body: { known: q.correct, session_id: sessionId.value } }); else if (q.type === "math") r = await api(`/math/${q.id}/answer`, { method: "POST", body: { answer: o, session_id: sessionId.value } }); else r = await api("/readings/1/answer", { method: "POST", body: { question_id: q.id, answer: o, session_id: sessionId.value } }); q.correct = r.correct ?? q.correct; combo.value = q.correct ? (r.combo || combo.value + 1) : 0; } catch (e) { fail(e); } }
async function nextQuestion() { if (questionIndex.value + 1 < questions.value.length) { questionIndex.value++; return; } try { result.value = await api(`/sessions/${sessionId.value}/finish`, { method: "POST" }); await load(); } catch (e) { fail(e); } }
function backHome() { result.value = null; view.value = "home"; }
async function loadAuth() { try { authMode.value = (await api("/parent/auth-mode", { child: false })).mode || "pin"; } catch {} }
async function login() { try { const r = await api("/parent/login", { method: "POST", child: false, body: { pin: pin.value } }); parentToken.value = r.token; localStorage.setItem("sp_parent_jwt", r.token); showLogin.value = false; pin.value = ""; await load(); if (!hasStudent.value) { view.value = "admin"; adminTab.value = "students"; } } catch (e) { fail(e); } }
function logout() { parentToken.value = ""; localStorage.removeItem("sp_parent_jwt"); students.value = []; currentStudent.value = 0; view.value = "home"; showLogin.value = false; }
async function enterAdmin(tab = "overview") { if (!isParent.value) { showLogin.value = true; return; } adminTab.value = tab; view.value = "admin"; await loadAdmin(); }
async function loadAdmin() { if (!isParent.value) return; try { const [tt, rr, ll] = await Promise.all([api(`/tasks?student_id=${currentStudent.value}`, { child: false }), api("/rewards", { child: false }), api(`/points/log?student_id=${currentStudent.value}`, { child: false })]); tasks.value = tt || []; rewards.value = rr || []; logs.value = ll || []; } catch (e) { fail(e); } }
async function addTask() { try { await api("/parent/tasks", { method: "POST", child: false, body: { ...newTask.value, student_id: currentStudent.value } }); newTask.value = { title: "", type: "学习", due_date: "", points: 5 }; notice.value = "任务已发布"; await loadAdmin(); } catch (e) { fail(e); } }
async function addReward() { try { await api("/parent/rewards", { method: "POST", child: false, body: newReward.value }); newReward.value = { name: "", cost_points: 20 }; notice.value = "奖励已添加"; await loadAdmin(); } catch (e) { fail(e); } }
async function addStudent() { if (!newStudent.value.name.trim()) { error.value = "请先填写学生姓名"; return; } try { await api("/parent/students", { method: "POST", child: false, body: newStudent.value }); newStudent.value = { name: "", username: "", avatar: "🐣", grade: 5 }; notice.value = "学生已创建，可以切换到学习工作台"; await load(); await loadAdmin(); } catch (e) { fail(e); } }
async function deleteStudent(id) { if (!confirm("确定删除这个学生及其学习数据吗？")) return; try { await api(`/parent/students/${id}`, { method: "DELETE", child: false }); await load(); await loadAdmin(); } catch (e) { fail(e); } }
async function deleteTask(id) { try { await api(`/parent/tasks/${id}`, { method: "DELETE", child: false }); await loadAdmin(); } catch (e) { fail(e); } }
async function savePin() { try { await api("/parent/set-pin", { method: "POST", child: false, body: { pin: newPin.value } }); newPin.value = ""; notice.value = "PIN 已更新"; } catch (e) { fail(e); } }
onMounted(async () => { await loadAuth(); if (isParent.value) await load(); else loading.value = false; });
</script>

<template>
  <main class="shell">
    <header class="topbar"><div class="brand"><div class="logo"><img src="/logo.png" alt="学霸星球" /></div><div><p class="eyebrow">STUDY PLANET · 学习成长空间</p><h1>学霸星球</h1><p>{{ isParent ? (view === 'admin' ? '家长管理中心' : '今天也要向前一点点') : '专为孩子设计的学习旅程' }}</p></div></div><div class="top-actions"><div v-if="hasStudent" class="xp-ring"><strong>{{ points }}</strong><span>积分</span></div><button v-if="isParent" class="parent-entry" @click="enterAdmin()">家长中心</button></div></header>
    <section v-if="!isParent" class="welcome card"><div class="welcome-art"><div class="planet">学</div><span class="orbit orbit-a"></span><span class="orbit orbit-b"></span></div><div class="welcome-copy"><p class="eyebrow orange">家长先登录，开启学习旅程</p><h2>先管理家庭成员<br />再让孩子开始学习</h2><p>家长登录后，可以创建孩子账号、安排每日任务、设置奖励，并查看学习成长记录。</p><button class="cta" @click="showLogin=true">进入家长登录 <span>→</span></button></div><div class="feature-strip"><span>✦ 安全的家庭空间</span><span>✦ 趣味化闯关学习</span><span>✦ 可追踪成长记录</span></div></section>
    <section v-else-if="loading" class="card loading">正在装载学习星球…</section>
    <section v-else-if="view === 'home'" class="home">
      <div v-if="!hasStudent" class="empty-state card"><div class="empty-icon">👨‍👩‍👧‍👦</div><p class="eyebrow orange">第一步 · 创建学习账号</p><h2>还没有学生账号</h2><p>请先在家长中心添加孩子，完成后这里就会出现专属学习工作台。</p><button class="cta" @click="enterAdmin('students')">去添加学生 <span>→</span></button></div>
      <template v-else><section class="dashboard-hero"><div><p class="eyebrow orange">{{ activeStudent?.name }}的学习星球</p><h2>今天想去哪里探索？</h2><p>每一次练习，都会变成成长路上的一颗星。</p></div><div class="hero-badge">{{ activeStudent?.avatar || '🐣' }}<small>Lv.{{ activeStudent?.level || 1 }}</small></div></section><div class="student-switcher"><span class="section-label">当前学习者</span><button v-for="s in students" :key="s.id" class="student" :class="{ active: s.id === currentStudent }" @click="switchStudent(s.id)"><span>{{ s.avatar || '🐣' }}</span>{{ s.name }}<b v-if="s.id === currentStudent">✓</b></button><button class="add-child" @click="enterAdmin('students')">＋ 添加孩子</button></div><section class="path card"><div class="section-heading"><div><p class="eyebrow">LEARNING MAP</p><h2>学习探索地图</h2></div><span class="map-progress">{{ totalStars() }} 颗星星</span></div><div class="units"><button v-for="u in units" :key="u.kind" class="unit" :class="u.className" @click="startUnit(u)"><span class="unit-icon">{{ u.icon }}</span><span class="stars">{{ '★'.repeat(starCount(u)) }}<i>{{ '☆'.repeat(3 - starCount(u)) }}</i></span><strong>{{ u.title }}</strong><small>{{ u.sub }}</small><em>开始探索 <b>→</b></em></button></div></section><div class="quick-grid"><button @click="enterAdmin('tasks')"><span class="quick-icon">✓</span><span><b>今日任务</b><small>{{ tasks.filter(t => t.status !== 'done').length || '查看任务安排' }}</small></span><i>→</i></button><button @click="enterAdmin('rewards')"><span class="quick-icon gift">◆</span><span><b>奖励商店</b><small>完成目标兑换奖励</small></span><i>→</i></button></div><section class="growth card"><div class="pet-zone"><div class="bubble">准备好闯关了吗？</div><div class="pet">🌟</div></div><div class="stats"><div><b>{{ points }}</b><span>我的积分</span></div><div><b>{{ maxCombo() }}</b><span>最高连击</span></div><div><b>{{ totalStars() }}</b><span>收集星星</span></div></div></section></template>
    </section>
    <section v-else-if="view === 'lesson'" class="lesson"><div class="lesson-top"><button class="close" @click="view='home'">×</button><div class="progress"><i :style="{ width: `${progress}%` }" /></div><b v-if="combo >= 2">连击 x{{ combo }}</b></div><article v-if="activeQuestion" class="card question"><p class="eyebrow orange">{{ { word: '词汇挑战', math: '数学挑战', reading: '阅读挑战' }[activeQuestion.type] }}</p><h2>{{ activeQuestion.title }}</h2><em>{{ activeQuestion.subtitle }}</em><div class="options"><button v-for="o in activeQuestion.options" :key="o" :disabled="activeQuestion.picked" :class="{ right: activeQuestion.picked && o === activeQuestion.answer, wrong: activeQuestion.picked === o && !activeQuestion.correct }" @click="selectOption(o)">{{ o }}</button></div><button v-if="activeQuestion.picked" class="cta continue" @click="nextQuestion">{{ questionIndex + 1 < questions.length ? '继续下一题 →' : '完成关卡 ✓' }}</button></article></section>
    <section v-else class="admin card"><nav class="admin-nav"><button :class="{active:adminTab==='overview'}" @click="adminTab='overview'">总览</button><button :class="{active:adminTab==='students'}" @click="adminTab='students'">孩子管理</button><button :class="{active:adminTab==='tasks'}" @click="adminTab='tasks'">学习任务</button><button :class="{active:adminTab==='rewards'}" @click="adminTab='rewards'">奖励商店</button><button :class="{active:adminTab==='logs'}" @click="adminTab='logs'">成长记录</button><button :class="{active:adminTab==='settings'}" @click="adminTab='settings'">账户设置</button></nav><div class="admin-head"><div><p class="eyebrow orange">PARENT SPACE</p><h2>家长管理中心</h2></div><div><button class="back-link" @click="view='home'">返回学习工作台</button><button class="danger-link" @click="logout">退出登录</button></div></div><div v-if="adminTab==='overview'" class="panel"><p class="muted">管理孩子的学习任务、奖励和成长记录。</p><div class="overview-grid"><div><b>{{ students.length }}</b><span>孩子账号</span></div><div><b>{{ tasks.filter(t=>t.status!=='done').length }}</b><span>待完成任务</span></div><div><b>{{ rewards.length }}</b><span>奖励项目</span></div><div><b>{{ points }}</b><span>当前积分</span></div></div><div class="admin-tip">💡 先添加孩子，再从学习工作台切换学习者；每个孩子的学习进度和积分独立保存。</div></div><div v-if="adminTab==='students'" class="panel"><h3>孩子账号</h3><p class="muted">创建后，孩子才能进入专属学习工作台。</p><div class="form-row"><input v-model="newStudent.name" placeholder="孩子姓名" /><input v-model="newStudent.username" placeholder="用户名（可选）" /><input v-model="newStudent.avatar" placeholder="头像" /><input v-model.number="newStudent.grade" type="number" placeholder="年级" /><button class="primary" @click="addStudent">创建孩子账号</button></div><div class="list"><div v-for="s in students" :key="s.id" class="list-row"><span class="avatar">{{ s.avatar || '🐣' }}</span><strong>{{ s.name }}</strong><small>{{ s.grade || 5 }}年级 · {{ s.username || '未设置用户名' }}</small><button class="select-link" @click="switchStudent(s.id)">{{ s.id === currentStudent ? '当前学习者' : '切换' }}</button><button class="danger-link" @click="deleteStudent(s.id)">删除</button></div><div v-if="!students.length" class="empty">还没有孩子账号，请先创建一个。</div></div></div><div v-if="adminTab==='tasks'" class="panel"><h3>学习任务</h3><div class="form-row"><input v-model="newTask.title" placeholder="任务名称，如：朗读课文" /><input v-model="newTask.due_date" type="date" /><input v-model.number="newTask.points" type="number" placeholder="奖励积分" /><button class="primary" @click="addTask">发布任务</button></div><div class="list"><div v-for="t in tasks" :key="t.id" class="list-row"><span class="task-check">✓</span><strong>{{ t.title }}</strong><small>+{{ t.points }} 积分 · {{ t.due_date || '今天' }}</small><button class="danger-link" @click="deleteTask(t.id)">删除</button></div><div v-if="!tasks.length" class="empty">还没有任务安排。</div></div></div><div v-if="adminTab==='rewards'" class="panel"><h3>奖励商店</h3><div class="form-row"><input v-model="newReward.name" placeholder="奖励名称，如：看一集动画片" /><input v-model.number="newReward.cost_points" type="number" placeholder="所需积分" /><button class="primary" @click="addReward">添加奖励</button></div><div class="reward-grid"><div v-for="r in rewards" :key="r.id" class="reward"><span class="reward-icon">◆</span><strong>{{ r.name }}</strong><b>{{ r.cost_points }} 积分</b></div><div v-if="!rewards.length" class="empty">还没有奖励项目。</div></div></div><div v-if="adminTab==='logs'" class="panel"><h3>成长记录</h3><div class="list"><div v-for="l in logs" :key="l.id" class="list-row"><span :class="l.delta > 0 ? 'gain' : 'loss'">{{ l.delta > 0 ? '+' : '' }}{{ l.delta }}</span><strong>{{ l.reason }}</strong><small>{{ l.created_at }}</small></div><div v-if="!logs.length" class="empty">完成学习后，这里会留下成长记录。</div></div></div><div v-if="adminTab==='settings'" class="panel"><h3>账户设置</h3><p class="muted">修改家长 PIN，保护家庭学习数据。</p><div class="form-row"><input v-model="newPin" type="password" placeholder="输入新的家长 PIN" /><button class="primary" @click="savePin">保存 PIN</button></div></div></section>
    <nav v-if="isParent && view !== 'lesson'" class="bottom-menu" aria-label="主菜单"><button :class="{ active: view === 'home' }" @click="view = 'home'"><span class="menu-icon">⌂</span><span>学习</span></button><button :class="{ active: view === 'admin' && adminTab === 'tasks' }" @click="enterAdmin('tasks')"><span class="menu-icon">✓</span><span>任务</span></button><button :class="{ active: view === 'admin' && adminTab === 'rewards' }" @click="enterAdmin('rewards')"><span class="menu-icon">★</span><span>奖励</span></button><button :class="{ active: view === 'admin' && ['overview', 'students', 'logs', 'settings'].includes(adminTab) }" @click="enterAdmin('overview')"><span class="menu-icon">♙</span><span>家长</span></button></nav>
    <div v-if="result" class="modal"><section class="result card"><div class="result-star">★</div><p class="eyebrow orange">MISSION COMPLETE</p><h2>闯关完成！</h2><p>答对 {{ result.correct }}/{{ result.total }} 题 · 最高连击 x{{ result.max_combo }}</p><button class="cta" @click="backHome">回到学习地图</button></section></div>
    <div v-if="showLogin" class="modal"><section class="dialog card"><button class="close" @click="showLogin=false">×</button><div class="login-mark">🔐</div><p class="eyebrow orange">PARENT ACCESS</p><h2>家长登录</h2><p v-if="authMode==='casdoor'">使用 Casdoor 账号安全登录</p><a v-if="authMode==='casdoor'" class="primary button-link" href="/api/parent/casdoor/login">前往登录</a><template v-else><p class="muted">登录后才能添加孩子和管理学习空间</p><input v-model="pin" type="password" placeholder="请输入家长 PIN" @keyup.enter="login" /><button class="cta full" @click="login">登录并进入管理中心</button></template></section></div><div v-if="error" class="modal"><section class="dialog card"><h2>操作未完成</h2><p>{{ error }}</p><button class="primary" @click="error=''">知道了</button></section></div><div v-if="notice" class="modal"><section class="dialog card"><div class="success-mark">✓</div><h2>操作成功</h2><p>{{ notice }}</p><button class="primary" @click="notice=''">好的</button></section></div>
  </main>
</template>
